import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import MapComponent from './components/MapComponent';
import RentPredictor from './components/rent-predictor/RentPredictor';
import Login from './components/Login'; 
import PropertyList from './components/PropertyList'; // <-- NAYA IMPORT

 const Home = () => (
  <div>
    {/* HERO SECTION WITH BACKGROUND IMAGE */}
    <div style={{
      backgroundImage: 'url("https://images.unsplash.com/photo-1522771731470-8598692fd1ce?q=80&w=2000&auto=format&fit=crop")',
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      minHeight: '85vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px',
      position: 'relative'
    }}>
      {/* Dark Overlay for better text readability */}
      <div style={{
        position: 'absolute',
        top: 0, left: 0, right: 0, bottom: 0,
        backgroundColor: 'rgba(0, 0, 0, 0.4)'
      }}></div>

      {/* GLASSMORPHISM CARD */}
      <div style={{
        position: 'relative',
        background: 'rgba(255, 255, 255, 0.15)', // Semi-transparent white
        backdropFilter: 'blur(16px)', // The magic blur effect
        WebkitBackdropFilter: 'blur(16px)', // Safari support
        border: '1px solid rgba(255, 255, 255, 0.3)',
        boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.37)',
        borderRadius: '24px',
        padding: '40px',
        maxWidth: '900px',
        width: '100%',
        color: '#fff',
        zIndex: 1
      }}>
        <h1 style={{ textAlign: "center", fontSize: "3rem", margin: "0 0 10px 0", textShadow: "0 2px 4px rgba(0,0,0,0.5)" }}>
          Find Your Perfect Student Stay
        </h1>
        <p style={{ textAlign: "center", fontSize: "1.2rem", marginBottom: "40px", color: "#e0e0e0" }}>
          AI-powered PG & Hostel recommendations tailored for you
        </p>

        {/* Iske andar hum Rent Predictor aur naya AI Recommender daal rahe hain */}
        <div style={{ display: 'flex', gap: '30px', flexWrap: 'wrap', justifyContent: 'center' }}>

          {/* AI MATCHMAKER FORM (UI PREVIEW) */}
          <div style={{ flex: '1', minWidth: '300px', background: 'rgba(0,0,0,0.4)', padding: '20px', borderRadius: '16px' }}>
            <h3 style={{ marginTop: 0, color: '#ffb74d' }}>✨ AI Matchmaker</h3>
            <p style={{ fontSize: '0.9rem', color: '#ccc' }}>Find the best PG based on your needs.</p>
            {/* Hum asli inputs next step me add karenge */}
            <button style={{ width: '100%', padding: '10px', marginTop: '10px', borderRadius: '8px', border: 'none', backgroundColor: '#80608f', color: 'white', cursor: 'pointer' }}>
              Find My Match
            </button>
          </div>

          {/* AAPKA RENT PREDICTOR */}
          <div style={{ flex: '1', minWidth: '300px', background: 'rgba(0,0,0,0.4)', padding: '20px', borderRadius: '16px' }}>
            <h3 style={{ marginTop: 0, color: '#64b5f6' }}>📈 Rent Predictor</h3>
            <div style={{ transform: 'scale(0.9)', transformOrigin: 'top' }}>
              <RentPredictor />
            </div>
          </div>

        </div>
      </div>
    </div>

    {/* NORMAL WHITE SECTION FOR PROPERTIES & MAP */}
    <div style={{ padding: "40px 20px", maxWidth: "1200px", margin: "0 auto" }}>
      <PropertyList />

      <hr style={{ margin: "40px 0", border: "1px solid #e6d9ef" }} />

      <h3 style={{ color: "#80608f", textAlign: "center", fontSize: "2rem" }}>Explore Campus Vicinity</h3>
      <MapComponent 
        lat={28.9731} 
        lng={77.6402} 
        pgName="MIET College Area" 
        rent={0} 
      />
    </div>
  </div>
);

function App() {
  return (
    <Router>
      <div style={{ backgroundColor: "#faf8fc", minHeight: "100vh" }}>
        <Navbar />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
